package app.oncare.personal;
import android.content.Context;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Same elapsed-time rules as iOS; never infers sensor stages. */
final class SleepTools {
 static double hours(long start,long end,double latency,double awake){double minutes=(end-start)/60000.0;if(start<=0||end<=start||minutes>1440||!Double.isFinite(latency)||latency<0||latency>90||!Double.isFinite(awake)||awake<0||minutes-latency-awake<1)throw new IllegalArgumentException("수면 시각과 입력한 분을 확인해주세요. 수면은 1분 이상, 전체 구간은 24시간 이내여야 해요.");return (minutes-latency-awake)/60;}
 static double span(List<Double> values){if(values.size()<2)return Double.NaN;List<Double> a=new ArrayList<>(values);Collections.sort(a);double gap=a.get(0)+1440-a.get(a.size()-1);for(int i=1;i<a.size();i++)gap=Math.max(gap,a.get(i)-a.get(i-1));return 1440-gap;}
 static void validate(JSONObject entry)throws JSONException{if(!entry.has("bedTime")&&!entry.has("wakeTime")&&!entry.has("awakeMinutes")&&!entry.has("sleep"))return;long bed=entry.getLong("bedTime"),wake=entry.getLong("wakeTime");double awake=entry.getDouble("awakeMinutes");if(!entry.getString("kind").equals("수면")||wake!=entry.getLong("date")||Math.abs(hours(bed,wake,0,awake)-entry.getDouble("value"))>0.001)throw new JSONException("sleep range");JSONObject details=entry.optJSONObject("sleep");if(details==null)return;JSONArray stages=details.optJSONArray("stages");if(stages==null||stages.length()>2048)throw new JSONException("stages");long previous=bed;double totalAwake=0;for(int i=0;i<stages.length();i++){JSONObject stage=stages.getJSONObject(i);long start=stage.getLong("start"),end=stage.getLong("end");String type=stage.getString("type");if(start<previous||end<=start||end>wake||!Arrays.asList("awake","light","deep","rem","sleeping","unknown").contains(type))throw new JSONException("stage range");previous=end;if(type.equals("awake"))totalAwake+=(end-start)/60000.0;}if(stages.length()>0&&Math.abs(totalAwake-awake)>1.0/60)throw new JSONException("awake");}
 static final class Store {
  final AtomicFile file;JSONObject session;String issue="";long lastObserved=0;
  Store(Context c,long now){file=new AtomicFile(new File(c.getFilesDir(),"sleep-session-v1.json"));if(file.getBaseFile().exists()||new File(file.getBaseFile()+".bak").exists())try(InputStream input=file.openRead()){byte[] bytes=ArticleActivity.readBytes(input);if(bytes.length>4096)throw new IOException();session=new JSONObject(new String(bytes,StandardCharsets.UTF_8));check(session,now);lastObserved=now;}catch(Exception e){issue="취침 상태를 읽지 못했어요. 초기화 전까지 원본을 보관합니다.";}}
  void check(JSONObject s,long now)throws Exception{String id=s.getString("id");if(!id.startsWith("sleep-timer:"))throw new IOException();UUID.fromString(id.substring(12));long start=s.getLong("startedAt"),checkpoint=s.getLong("checkpointAt");if(s.getInt("version")!=1||start<=0||checkpoint<start||now<checkpoint||now<lastObserved)throw new IllegalArgumentException("기기 시각이 이전으로 바뀌었어요. 시각을 확인하거나 초기화해주세요.");if(s.has("finishedAt")){if(s.getLong("finishedAt")!=checkpoint)throw new IOException();hours(start,checkpoint,s.getDouble("latency"),s.getDouble("awake"));}else if(now-start>86400000L)throw new IllegalArgumentException("24시간을 넘긴 취침 상태를 확인해주세요.");}
  void save(JSONObject next,long now)throws Exception{check(next,now);FileOutputStream output=null;try{output=file.startWrite();output.write(next.toString().getBytes(StandardCharsets.UTF_8));file.finishWrite(output);session=next;issue="";lastObserved=now;}catch(Exception e){if(output!=null)file.failWrite(output);throw new IOException("취침 상태를 저장하지 못했어요. 기존 상태는 유지합니다.");}}
  void start(long now)throws Exception{if(session!=null||!issue.isEmpty())throw new IllegalStateException("기존 취침 상태를 먼저 확인해주세요.");save(new JSONObject().put("version",1).put("id","sleep-timer:"+UUID.randomUUID()).put("startedAt",now).put("checkpointAt",now),now);}
  void observe(long now)throws Exception{if(session==null)return;check(session,now);lastObserved=now;}
  void checkpoint(long now)throws Exception{if(session==null||session.has("finishedAt"))return;check(session,now);save(new JSONObject(session.toString()).put("checkpointAt",now),now);}
  JSONObject finish(long now,double latency,double awake)throws Exception{check(session,now);JSONObject next=new JSONObject(session.toString());if(!next.has("finishedAt")){hours(next.getLong("startedAt"),now,latency,awake);next.put("finishedAt",now).put("checkpointAt",now).put("latency",latency).put("awake",awake);save(next,now);}long end=next.getLong("finishedAt"),start=next.getLong("startedAt");double l=next.getDouble("latency"),a=next.getDouble("awake");return new JSONObject().put("id",next.getString("id")).put("kind","수면").put("date",end).put("value",hours(start,end,l,a)).put("note","취침·기상 시각과 직접 입력한 잠드는 시간으로 계산").put("bedTime",start+Math.round(l*60000)).put("wakeTime",end).put("awakeMinutes",a);}
  void reset(){file.delete();if(file.getBaseFile().exists()||new File(file.getBaseFile()+".bak").exists())throw new IllegalStateException("취침 상태 정리를 다시 시도해주세요.");session=null;issue="";lastObserved=0;}
 }
}
